<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class mdyeingmethod extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY."mdyeingmodel");        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();        $this->limit = LIMITPERPAGE;    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId		    									    = $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if($VarId<>'' && base64_decode(urldecode($VarId))) {            $VarUserId                                          = base64_decode(urldecode($VarId));            $ArrResults     									= $this->mdyeingmodel->fnGetDyeingMethodInfo('','',                $VarUserId);            $ArrData['ArrBasicInfo']	    				    = $ArrResults[0];            $ArrData['VarId']					                = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditdyeingmethod', $ArrData);    }    public function updateDyeingInfo() {        $ArrResult                                              = array();        $VarMethodName				    						= xssclean($this->input->post('mn'));        $VarStatus												= xssclean($this->input->post('s'));        $VarId       											= xssclean($this->input->post('id'));        $ArrUserInfo = fnGetUserLoggedInfo(1);        if($VarMethodName<>'') {            $ArrUpdateData                                      = array('id'=>$VarId,'dyeingname'=>$VarMethodName,                'status' => $VarStatus, 'updatedby' => $ArrUserInfo['id'], 'companyid' => $ArrUserInfo['companyid'], 'dateupdated' => date('Y-m-d H:i:s'));            if($VarId=='' || $VarId==0) {                $ArrUpdateData['datecreated']                   = date('Y-m-d H:i:s');            }            $ArrStatus                                          = $this->mdyeingmodel->saveDyeingMethodInfo($ArrUpdateData);            echo json_encode($ArrStatus);unset($ArrStatus);unset($ArrUpdateData);die;        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg']								    = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function managedyeingmethod() {        $VarFrom												= xssclean($this->input->post('rfrom'));        $VarMethodName											= xssclean($this->input->post('mn'));        $VarStatus  											= xssclean($this->input->post('s'));        $sortbyClickEvent									    = xssclean($this->input->post('sortorder'));        $VarColumnId									        = xssclean($this->input->post('columnId'));        $VarAlphaFilter	   										= xssclean($this->input->post('afilter'));        if($VarFrom==1) {            $VarURLSegment										= 4;            $this->load->library('pagination');            $config['base_url']									= base_url().CNFCOMPANY.'mdyeingmethod/managedyeingmethod/';            $config['total_rows']								= $this->mdyeingmodel->fnCountDyeingMethod($VarMethodName,$VarStatus,$VarAlphaFilter);            $config['per_page']									= $this->limit;            $config['uri_segment']								= $VarURLSegment;            $offset												= $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby												= "d.dateupdated";            $sortorder											= "desc";            if($sortbyClickEvent <> '') {                $sortorder = $sortbyClickEvent;            }            if($VarColumnId <> '') {                $Arrcolumns = array("1" => 'd.dyeingname', '2' => 'd.status', '3' => 'u.contactname', '4' => 'd.dateupdated');                if(array_key_exists($VarColumnId,$Arrcolumns)) {                    $sortby = $Arrcolumns[$VarColumnId];                }            }            $ArrDyeingMethodList								= $this->mdyeingmodel->fnListDyeingMethod($VarMethodName,$VarStatus,$this->limit,$offset,$sortby,$sortorder,$VarAlphaFilter)->result();            if($VarAlphaFilter <> '') {                $ArrDyeingMethodList								= $this->mdyeingmodel->fnListDyeingMethod($VarMethodName,$VarStatus,$this->limit,$offset,$sortby,$sortorder,$VarAlphaFilter)->result();            }            $data['pagination']									= $this->pagination->create_linkswithajax('DyeingMethod');            $i=0;            $ArrFnlList										    = array();            $ArrStatus                                          = unserialize(ARRSTATUS);            foreach ($ArrDyeingMethodList as $ObjDyeing){                $ArrFnlList[$i]['id']						    = $ObjDyeing->id;                $ArrFnlList[$i]['n']						    = $ObjDyeing->dyeingname;                $ArrFnlList[$i]['ub']						    = $ObjDyeing->contactname;                $ArrFnlList[$i]['s']						    = $ArrStatus[$ObjDyeing->status];                $ArrFnlList[$i]['du']						    = date('d-m-Y H:i:s',strtotime($ObjDyeing->dateupdated));                $i=$i+1;            }            echo json_encode(array('errcode'=>1,'cn'=>$config['total_rows'],'ct'=>$i,'re'=>$ArrFnlList,'pa'=>base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managedyeingmethod');        }    }    function changemStatus() {        $VarActDeactOption										= xssclean($this->input->post('actdeactFabType'));        $VarCid 	   										    = xssclean($this->input->post('cid'));        if($VarActDeactOption <> '' && $VarCid <> '') {            $this->mdyeingmodel->fnChangeComStat($VarCid,$VarActDeactOption);        }        echo json_encode(array('errcode'=> 1));        die;    }}